SA, SM, T_OPT = 0.3679, 2.439, 1.431


class Lesson(Base):
    def construct(self):
        self.title("22.6", "相平面上的时间最优", "Time-optimal motion in the phase plane")
        ax = Axes(x_range=[0, 3.6, 0.5], y_range=[0, 6, 1], x_length=9.6, y_length=4.4, tips=False,
                  axis_config={"stroke_width": 1.5, "color": GREY_B, "include_numbers": True, "font_size": 20})
        ax.move_to(np.array([-1.3, -0.2, 0]))
        xl = MathTex(r"\sigma\ (\mathrm{rad})", font_size=26, color=INK).next_to(ax.x_axis, RIGHT, buff=0.15)
        yl = MathTex(r"\dot\sigma\ (\mathrm{rad/s})", font_size=26, color=INK).next_to(ax.y_axis, UP, buff=0.1)
        marks = VGroup(*[DashedLine(ax.c2p(s, 0), ax.c2p(s, 6), color=GREY_C, stroke_width=1) for s in (SA, SM)],
                       Text("A", font=CJK, font_size=22, color=INK).move_to(ax.c2p(SA + 0.08, 5.7)),
                       Text("M", font=CJK, font_size=22, color=INK).move_to(ax.c2p(SM + 0.1, 5.7)))
        self.caption("横轴是沿路径走了多远，纵轴是走得多快；走完的时间 T = ∫ dσ/σ̇，σ̇ 越大越快",
                     "Horizontal: how far along the path; vertical: how fast. T = ∫ dσ/σ̇, so larger σ̇ is faster", wait=0)
        self.play(Create(ax), FadeIn(xl), FadeIn(yl), FadeIn(marks), run_time=1.5)
        sv = VMobject(color=GREY_B, stroke_width=3).set_points_as_corners([ax.c2p(s, min(v, 6)) for s, v in zip(SIG, SV)])
        mvc = DashedVMobject(VMobject(color=ORANGE, stroke_width=3).set_points_as_corners([ax.c2p(s, min(v, 6)) for s, v in zip(SIG, MVC)]),
                             num_dashes=80)
        self.caption("灰：关节速度限值给出的上限；橙：再加上加速度限值，速度上限曲线",
                     "Grey: the bound from joint speed limits; orange: with acceleration limits too, the maximum velocity curve", wait=0)
        self.play(Create(sv), run_time=1.5)
        self.play(Create(mvc), run_time=1.5)
        n = len(SIG)
        kk = VMobject(color=RED, stroke_width=4).set_points_as_corners([ax.c2p(SIG[i], KK[i]) for i in range(n - 1, -1, -1)])
        self.caption("第一遍从终点往回算：每一点最多能多快，才刹得住（可控集的上界，红）",
                     "Pass 1, backwards from the end: the highest speed from which it can still stop (controllable set, red)", wait=0)
        self.play(Create(kk), run_time=3.0, rate_func=linear)
        tk = ValueTracker(0.0)

        def clock():
            t = tk.get_value()
            s = float(np.interp(t, TT, SIG))
            v = float(np.interp(t, TT, XS))
            m = int(np.searchsorted(TT, t, side="right"))
            pts = [ax.c2p(a, b) for a, b in zip(SIG[:m], XS[:m])] + [ax.c2p(s, v)]
            line = VMobject(color=BLUE, stroke_width=6)
            if len(pts) >= 2:
                line.set_points_as_corners(pts)
            return VGroup(line, Dot(ax.c2p(s, v), radius=0.09, color=YELLOW),
                          Text(f"t = {t:.2f} s", font=CJK, font_size=24, color=INK).move_to(np.array([5.0, 1.8, 0])))

        self.caption("第二遍从起点往前走：能加速就全力加速，但不越过红线；所得的速度曲线就是时间最优的（蓝）",
                     "Pass 2, forwards: accelerate as hard as allowed without crossing the red line; the result is time-optimal (blue)", wait=0)
        self.add(always_redraw(clock))
        self.play(tk.animate.set_value(T_OPT), run_time=6.0, rate_func=linear)
        self.caption(f"走完这条路径只要 {T_OPT:.3f} s；样条整体缩放要 1.774 s",
                     f"The path takes only {T_OPT:.3f} s; the uniformly scaled spline needs 1.774 s", wait=2.0)
        self.card([["沿给定路径的时间最优", "Time-optimal motion along a given path"],
                   MathTex(r"x = \dot s^2,\quad u = \ddot s,\qquad \frac{\mathrm dx}{\mathrm ds} = 2u", font_size=40),
                   MathTex(r"-a_i \le \theta_i'(s)\,u + \theta_i''(s)\,x \le a_i,\qquad x \le \frac{v_i^2}{\theta_i'(s)^2}", font_size=40),
                   ["约束对 (x, u) 是线性的：往回算可控集，往前走取最大加速度", "Constraints are linear in (x, u): controllable set backwards, maximum acceleration forwards"]])
